/**
 * Vehicles API - Hybrid Approach
 * Combines detailed vehicle database with legacy vehicle list
 * Provides filtering, sorting, and querying capabilities for vehicles
 * 
 * HYBRID SYSTEM:
 * - Detailed vehicles: Full data from vehicleDatabase (142 vehicles)
 * - Legacy vehicles: Auto-generated data from carDatabase (500+ vehicles)
 */

import { vehicleImageFor } from '../utils/vehicleImages';
import { carDatabase } from '../utils/vehicleDatabase';

export interface Vehicle {
  id: string;
  year: string;
  make: string;
  model: string;
  trim?: string;
  bodyStyle: string;
  image: string;
  galleryImages?: string[];
  priceRange: string;
  priceMin: number;
  priceMax: number;
  staffRating: number;
  communityRating: number;
  reviewCount: number;
  fuelType: 'Gas' | 'Electric' | 'Hybrid' | 'Plug-in Hybrid' | 'Diesel';
  drivetrain: 'FWD' | 'RWD' | 'AWD' | '4WD';
  transmission: 'Automatic' | 'Manual' | 'CVT';
  mpg?: string;
  horsepower?: number;
  seatingCapacity?: number;
  cargoSpace?: number;
  features?: string[];
  slug: string;
  featured?: boolean;
  award?: string;
  tags?: string[];
}

export interface VehicleFilters {
  bodyStyle?: string[];
  make?: string[];
  year?: string[];
  priceMin?: number;
  priceMax?: number;
  fuelType?: string[];
  drivetrain?: string[];
  minRating?: number;
  search?: string;
}

export interface VehicleSortOptions {
  sortBy?: 'price' | 'rating' | 'name' | 'year' | 'popularity';
  sortOrder?: 'asc' | 'desc';
}

export interface VehicleQueryOptions extends VehicleFilters, VehicleSortOptions {
  limit?: number;
  offset?: number;
  excludeIds?: string[];
  featured?: boolean;
}

